package com.zoutrankil.data.repository;
import com.zoutrankil.data.service.MoneyflowDcSource;
import com.zoutrankil.data.service.MoneyflowDcSyncJobOwner;

import com.zoutrankil.data.domain.*;
import com.zoutrankil.data.domain.temporal.TemporalValues;
import com.zoutrankil.data.mapper.MoneyflowDcMapper;
import com.zoutrankil.data.service.StaticTargetIdentity;
import com.zoutrankil.data.service.VerifiedBatchExecutor;
import io.questdb.client.QuestDB;
import io.questdb.client.Sender;
import org.springframework.jdbc.core.JdbcTemplate;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.Duration;
import java.time.LocalDate;
import java.util.*;

/** Isolated DEDUP=true QWP writer with full-key readback and target-generation checks. */
public final class MoneyflowDcWritePort implements VerifiedBatchExecutor.Port<MoneyflowDc,MoneyflowDcKey> {
    public static final int MAX_BATCH_ROWS=250,MAX_BATCH_BYTES=1024*1024,MAX_DATE_ROWS=MoneyflowDcSource.MAX_DAILY_ROWS;
    private static final Duration ACK_TIMEOUT=Duration.ofSeconds(10);private static final List<String> NUMERIC=MoneyflowDcDataset.columns().stream().map(DatasetDefinition.Column::storageName).filter(f->!Set.of("ts_code","trade_date","name").contains(f)).toList();
    public static final VerifiedBatchExecutor.Codec<MoneyflowDc,MoneyflowDcKey> CODEC=new VerifiedBatchExecutor.Codec<>(){
        @Override public MoneyflowDcKey key(MoneyflowDc row){return row==null?null:row.key();}
        @Override public byte[] canonicalBytes(MoneyflowDc row){try{return JobDefinitionJson.mapper().writeValueAsBytes(new MoneyflowDcMapper().values(row).asMap());}catch(Exception e){throw new IllegalArgumentException("Cannot encode moneyflow_dc row",e);}}
        @Override public int estimatedTransportBytes(MoneyflowDc row,byte[] canonical){return Math.addExact(Math.multiplyExact(canonical.length,4),256);}};
    private final String table,targetId;private final JdbcTemplate jdbc;private final QuestDB questdb;private final MoneyflowDcMapper mapper=new MoneyflowDcMapper();private volatile boolean senderStopped;
    public MoneyflowDcWritePort(String table,String targetId,JdbcTemplate jdbc,QuestDB questdb){MoneyflowDcDataset.requireIsolatedTable(table);if(targetId==null||!targetId.matches("static-v2-[0-9a-f]{64}"))throw new IllegalArgumentException("Frozen D026 physical target identity required");this.table=table;this.targetId=targetId;this.jdbc=new JdbcTemplate(Objects.requireNonNull(jdbc).getDataSource());this.jdbc.setQueryTimeout(20);this.jdbc.setMaxRows(50_001);this.questdb=Objects.requireNonNull(questdb);}
    @Override public void preflight(){requireTarget();QuestDbWriteChecks.preflight(jdbc,table,MoneyflowDcDataset.definition(table));requireTarget();}
    @Override public void send(List<MoneyflowDc> rows)throws Exception{if(rows==null||rows.isEmpty()||rows.size()>MAX_BATCH_ROWS)throw new IllegalArgumentException("Nonempty moneyflow_dc batch of at most 250 rows required");preflight();senderStopped=false;
        DatasetWritePreparation.prepare(MoneyflowDcDataset.definition(table),rows,mapper::values,new DatasetWritePreparation.Limits(MAX_BATCH_ROWS,MAX_BATCH_BYTES));long bytes=0;for(var row:rows){bytes=Math.addExact(bytes,CODEC.estimatedTransportBytes(row,CODEC.canonicalBytes(row)));if(bytes>MAX_BATCH_BYTES)throw new IllegalArgumentException("moneyflow_dc batch exceeds 1 MiB before send");}
        boolean attempted=false;try(Sender sender=questdb.borrowSender()){for(var row:rows){var line=sender.table(table).symbol("ts_code",row.tsCode());if(row.name()!=null)line.stringColumn("name",row.name());for(String f:NUMERIC){Double value=numeric(row,f);if(value!=null)line.doubleColumn(f,value);}line.at(new TemporalValues.CalendarTimestamp(row.tradeDate()).storageCarrier());}
            long sequence=sender.flushAndGetSequence();attempted=true;if(sequence<0||!sender.awaitAckedFsn(sequence,ACK_TIMEOUT.toMillis()))throw new IllegalStateException("moneyflow_dc QWP acknowledgement unknown; reconcile complete keys before replay");
        }catch(Exception e){attempted=true;throw e;}finally{senderStopped=attempted;}}
    @Override public List<MoneyflowDc> readback(List<MoneyflowDcKey> keys){if(keys==null||keys.isEmpty()||keys.size()>MAX_BATCH_ROWS||new HashSet<>(keys).size()!=keys.size())throw new IllegalArgumentException("1..250 unique moneyflow_dc readback keys required");requireTarget();var clauses=new ArrayList<String>();var args=new ArrayList<Object>();for(var key:keys){clauses.add("(ts_code=? AND trade_date=cast(? AS TIMESTAMP))");args.add(key.tsCode());args.add(micros(key.tradeDate()));}return jdbc.query(select()+" WHERE "+String.join(" OR ",clauses)+" ORDER BY trade_date,ts_code LIMIT "+(keys.size()+1),this::physical,args.toArray());}
    public List<MoneyflowDc> readDate(LocalDate date){requireTarget();var rows=jdbc.query(select()+" WHERE trade_date=cast(? AS TIMESTAMP) ORDER BY ts_code LIMIT "+(MAX_DATE_ROWS+1),this::physical,micros(date));if(rows.size()>MAX_DATE_ROWS)throw new IllegalStateException("Physical moneyflow_dc date reaches source cap");return List.copyOf(rows);}
    public List<MoneyflowDc> readRange(LocalDate from,LocalDate to){if(from==null||to==null||from.isAfter(to))throw new IllegalArgumentException("Ordered moneyflow_dc date range required");requireTarget();long days=java.time.temporal.ChronoUnit.DAYS.between(from,to)+1;if(days>MoneyflowDcSyncJobOwner.MAX_WINDOW_DAYS)throw new IllegalArgumentException("moneyflow_dc physical range exceeds five-day run bound");var rows=jdbc.query(select()+" WHERE trade_date>=cast(? AS TIMESTAMP) AND trade_date<cast(? AS TIMESTAMP) ORDER BY trade_date,ts_code LIMIT "+(MoneyflowDcSyncJobOwner.MAX_WINDOW_DAYS*MAX_DATE_ROWS+1),this::physical,micros(from),micros(to.plusDays(1)));if(rows.size()>MoneyflowDcSyncJobOwner.MAX_WINDOW_DAYS*MAX_DATE_ROWS)throw new IllegalStateException("moneyflow_dc physical range exceeds run bound");return List.copyOf(rows);}
    public TargetRange readTargetRange(){requireTarget();String sql="SELECT cast(min(trade_date) AS long) AS min_micros,cast(max(trade_date) AS long) AS max_micros,count(*) AS row_count FROM \""+table+"\"";return jdbc.query(sql,rs->{if(!rs.next())throw new SQLException("moneyflow_dc target range unavailable");Object min=rs.getObject(1),max=rs.getObject(2),count=rs.getObject(3);if(!(count instanceof Number c))throw new SQLException("moneyflow_dc target count unavailable");if(min==null&&max==null){if(c.longValue()!=0)throw new SQLException("Empty moneyflow_dc range has nonzero count");return new TargetRange(null,null,0);}if(!(min instanceof Number a)||!(max instanceof Number b)||c.longValue()<1)throw new SQLException("Invalid moneyflow_dc target range/count");return new TargetRange(date(a.longValue()),date(b.longValue()),c.longValue());});}
    public List<LocalDate> readExistingDates(){requireTarget();var values=jdbc.query("SELECT DISTINCT cast(trade_date AS long) AS trade_date_micros FROM \""+table+"\" ORDER BY trade_date_micros LIMIT 10001",(rs,n)->date(rs.getLong(1)));if(values.size()>10000)throw new IllegalStateException("moneyflow_dc distinct-date inventory exceeds 10000");return List.copyOf(values);}
    public record TargetRange(LocalDate min,LocalDate max,long rows){public TargetRange{if((min==null)!=(max==null)||min!=null&&min.isAfter(max)||rows<0||(min==null)!=(rows==0))throw new IllegalArgumentException("Invalid moneyflow_dc target range/count");}public boolean empty(){return rows==0;}}
    @Override public boolean walSettled(){requireTarget();return QuestDbWriteChecks.walSettled(jdbc,table);}@Override public boolean uncertainSenderStopped(){return senderStopped;}
    private static Double numeric(MoneyflowDc r,String f){return switch(f){case "pct_change"->r.pctChange();case "close"->r.close();case "net_amount"->r.netAmount();case "net_amount_rate"->r.netAmountRate();case "buy_elg_amount"->r.buyElgAmount();case "buy_elg_amount_rate"->r.buyElgAmountRate();case "buy_lg_amount"->r.buyLgAmount();case "buy_lg_amount_rate"->r.buyLgAmountRate();case "buy_md_amount"->r.buyMdAmount();case "buy_md_amount_rate"->r.buyMdAmountRate();case "buy_sm_amount"->r.buySmAmount();default->r.buySmAmountRate();};}
    private String select(){return "SELECT ts_code,cast(trade_date AS long) AS trade_date_micros,name,pct_change,close,net_amount,net_amount_rate,buy_elg_amount,buy_elg_amount_rate,buy_lg_amount,buy_lg_amount_rate,buy_md_amount,buy_md_amount_rate,buy_sm_amount,buy_sm_amount_rate FROM \""+table+"\"";}
    private MoneyflowDc physical(ResultSet rs,int n)throws SQLException{Object raw=rs.getObject("trade_date_micros");if(!(raw instanceof Number micros))throw new SQLException("moneyflow_dc trade_date required");var v=new LinkedHashMap<String,Object>();v.put("ts_code",rs.getString("ts_code"));v.put("trade_date",date(micros.longValue()));v.put("name",rs.getString("name"));for(String f:NUMERIC){Object x=rs.getObject(f);v.put(f,x==null?null:((Number)x).doubleValue());}try{return mapper.fromValues(new DatasetValues(v));}catch(RuntimeException e){throw new SQLException("Invalid physical moneyflow_dc row",e);}}
    private void requireTarget(){var rows=jdbc.queryForList("SELECT id,directoryName FROM tables() WHERE table_name=?",table);if(rows.size()!=1||!(rows.getFirst().get("id") instanceof Number id)||!(rows.getFirst().get("directoryName") instanceof String dir)||!targetId.equals(StaticTargetIdentity.identify(jdbc,table,id.longValue(),dir)))throw new IllegalStateException("D026 QuestDB physical target identity changed");}
    private static long micros(LocalDate date){return new TemporalValues.CalendarTimestamp(date).storageEpoch(TemporalValues.EpochUnit.MICROS);}private static LocalDate date(long micros){return TemporalValues.CalendarTimestamp.fromStorageEpoch(micros,TemporalValues.EpochUnit.MICROS).date();}
}
